UPDATE checklist_items SET description = 'Send the welcome email before his start date with his login credentials, first-day logistics, and his buddy''s contact info. Send it to his personal inbox and ask him to confirm receipt — everything else on this list starts from there.' WHERE id = 13 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Raise the request for his laptop and any additional assets (monitor, headset, dock) before he starts. Confirm with IT that the request is submitted and flag anything specific his role needs, so it''s ready on day 1.' WHERE id = 14 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Submit the access card request with Admin ahead of his start date. Have him collect the card from reception on his first morning and test it on the main entrance and his floor before he settles at his desk.' WHERE id = 15 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Arrange the laptop handover with IT in B2. Once he has it, he logs in with the credentials from the welcome email, connects to VPN, and verifies he can access Slack, email, and the team''s shared drive.' WHERE id = 9 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Have him install the VPN client from the IT portal and register his device for multi-factor authentication. Make sure he tests the connection from off-site once, so he isn''t troubleshooting it the first time he works remotely.' WHERE id = 16 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Raise a GitHub access request through the IT service portal using his GitHub username. He''s added to the organization first — repository-level permissions come in a separate step.' WHERE id = 17 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Request access to the team''s Jira project so he can see the current sprint board and pick up his first ticket. Once he''s in, check that his account is assigned to the right project role.' WHERE id = 18 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'SonarQube is where code quality and coverage are tracked on every pull request. Request an account for him and confirm he can view the dashboards for the projects the team owns.' WHERE id = 19 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Submit an AWS access request specifying the accounts and environments his role needs. Approve the permission set, and make sure he sets up MFA on first login.' WHERE id = 20 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Submit an Azure access request for the subscriptions and resource groups the team works with. As with AWS, approve the scope and confirm he enables MFA when he first signs in.' WHERE id = 21 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'The DEV distribution list carries release notes, deployment windows, and engineering-wide announcements. Ask IT to add him, then confirm he''s receiving mail on it.' WHERE id = 22 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Tell him which channels matter for the team — usually the team channel, the wider engineering channel, and any project-specific ones. Add him to them, and ask him to set a profile photo and post a short intro in the team channel.' WHERE id = 23 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Once he''s in the GitHub organization, add him to the specific teams and repositories he''ll work on. Ask him to clone one repo to confirm access works, and walk him through the branch protection rules so he knows how pull requests and reviews are handled here.' WHERE id = 24 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Send him to the HR desk on the 5th floor to complete his tax forms, emergency contact details, and benefits elections in person. This should be done within his first week to avoid delays in payroll setup.' WHERE id = 11 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Have him provide his bank account information to HR so his salary can be processed. Get this in as early in the month as possible — details received after the payroll cut-off roll over to the following cycle.' WHERE id = 25 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Assign the mandatory onboarding modules in SuccessFactors — security awareness, code of conduct, and any role-specific courses — and check that he logs in to complete them. These are tracked for compliance, so they should be done within his first few weeks.' WHERE id = 26 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Point him to the full handbook in the Company Hub, covering PTO policy, expense guidelines, working hours, and code of conduct. He doesn''t need to memorize it — one skim so he knows what''s in there and where to look it up later.' WHERE id = 12 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Send a short introduction email to the UK team so they know who has joined, his role, which squad he''s on, and how to reach him. Copy him in so he has the names and email addresses in one place from day one.' WHERE id = 30 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Send him the free 16Personalities assessment (about 10 minutes) and ask him to share his result with you and the team. It''s a light conversation starter about working styles — there are no right or wrong outcomes.' WHERE id = 27 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Name his buddy in the welcome email and brief them beforehand. The buddy is his go-to for questions that feel too small to ask his manager — ask them to message him on day 1 and book 30 minutes that first week.' WHERE id = 10 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Book a 1:1 with him during his first week to align on expectations for the first 30 days. Add him to the team intro and daily standup invites so he meets the team early.' WHERE id = 28 AND (description IS NULL OR description = '');
UPDATE checklist_items SET description = 'Add him to the invites for the team''s recurring ceremonies — sprint planning, refinement, review, and retrospective. Ask his buddy to walk him through how the sprint cycle runs before his first one.' WHERE id = 29 AND (description IS NULL OR description = '');